solutions.java:
class Solution {
    private int[] nums;

    public int countTarget(int[] nums, int target) {
        this.nums = nums;
        int l = countTarget(target);
        int r = countTarget(target + 1);
        return r - l;
    }

    private int countTarget(int x) {
        int l = 0, r = nums.length;
        while (l < r) {
            int mid = (l + r) >>> 1;
            if (nums[mid] >= x) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }
        return l;
    }
}

